
import { Link } from 'react-router-dom';
import { rankingProducts } from '../../../mocks/products';

interface RelatedProductsProps {
  relatedIds: number[];
}

export default function RelatedProducts({ relatedIds }: RelatedProductsProps) {
  const related = rankingProducts.filter((p) => relatedIds.includes(p.id));

  if (related.length === 0) return null;

  return (
    <div>
      <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2 border-b-2 border-red-500 pb-2">
        <i className="ri-links-line text-red-600 w-5 h-5 flex items-center justify-center"></i>
        関連商品
      </h2>
      <div className="grid grid-cols-3 gap-4">
        {related.map((product) => (
          <Link
            key={product.id}
            to={`/product/${product.id}`}
            className="bg-white border border-gray-200 rounded-lg p-3 hover:shadow-lg transition-shadow cursor-pointer"
          >
            <div className="w-full h-36 bg-gray-100 rounded overflow-hidden mb-3">
              <img src={product.image} alt={product.name} className="w-full h-full object-cover object-top" />
            </div>
            <div className="flex gap-1 mb-2 flex-wrap">
              {product.tags.map((tag, idx) => (
                <span
                  key={idx}
                  className={`text-xs px-2 py-0.5 rounded whitespace-nowrap ${
                    tag === '在庫有り' ? 'bg-green-500 text-white' :
                    tag === 'NEW' ? 'bg-red-500 text-white' :
                    tag === '送料無料' ? 'bg-blue-500 text-white' :
                    tag === 'SALE' ? 'bg-orange-500 text-white' :
                    'bg-purple-500 text-white'
                  }`}
                >
                  {tag}
                </span>
              ))}
            </div>
            <p className="text-xs text-gray-500">{product.brand}</p>
            <h3 className="text-sm font-bold text-gray-800 mb-1 line-clamp-2">{product.name}</h3>
            <p className="text-lg font-bold text-red-600">¥{product.price.toLocaleString()}</p>
          </Link>
        ))}
      </div>
    </div>
  );
}
