
import { useState } from 'react';

interface ProductImagesProps {
  images: string[];
  name: string;
}

export default function ProductImages({ images, name }: ProductImagesProps) {
  const [selectedImage, setSelectedImage] = useState(0);

  return (
    <div>
      <div className="w-full h-[460px] bg-gray-100 rounded-lg overflow-hidden mb-3 border border-gray-200">
        <img
          src={images[selectedImage]}
          alt={name}
          className="w-full h-full object-contain object-top"
        />
      </div>
      <div className="flex gap-2">
        {images.map((img, idx) => (
          <button
            key={idx}
            onClick={() => setSelectedImage(idx)}
            className={`w-20 h-20 rounded border-2 overflow-hidden flex-shrink-0 cursor-pointer transition-all ${
              selectedImage === idx
                ? 'border-red-500 shadow-md'
                : 'border-gray-200 hover:border-gray-400'
            }`}
          >
            <img src={img} alt={`${name} ${idx + 1}`} className="w-full h-full object-cover object-top" />
          </button>
        ))}
      </div>
    </div>
  );
}
