
interface Review {
  user: string;
  rating: number;
  date: string;
  comment: string;
}

interface ProductReviewsProps {
  reviews: Review[];
}

export default function ProductReviews({ reviews }: ProductReviewsProps) {
  const avgRating = reviews.length > 0
    ? (reviews.reduce((sum, r) => sum + r.rating, 0) / reviews.length).toFixed(1)
    : '0';

  return (
    <div>
      <h2 className="text-lg font-bold text-gray-800 mb-4 flex items-center gap-2 border-b-2 border-red-500 pb-2">
        <i className="ri-chat-quote-line text-red-600 w-5 h-5 flex items-center justify-center"></i>
        カスタマーレビュー（{reviews.length}件）
      </h2>

      <div className="flex items-center gap-4 mb-6 bg-amber-50 border border-amber-200 rounded-lg p-4">
        <div className="text-center">
          <p className="text-3xl font-bold text-orange-600">{avgRating}</p>
          <div className="flex text-yellow-500 text-sm mt-1">
            {[...Array(5)].map((_, i) => (
              <i key={i} className={i < Math.round(Number(avgRating)) ? 'ri-star-fill' : 'ri-star-line'}></i>
            ))}
          </div>
          <p className="text-xs text-gray-500 mt-1">{reviews.length}件の評価</p>
        </div>
        <div className="flex-1">
          {[5, 4, 3, 2, 1].map((star) => {
            const count = reviews.filter((r) => r.rating === star).length;
            const pct = reviews.length > 0 ? (count / reviews.length) * 100 : 0;
            return (
              <div key={star} className="flex items-center gap-2 text-xs mb-1">
                <span className="w-8 text-gray-600 text-right">{star}★</span>
                <div className="flex-1 bg-gray-200 rounded-full h-2 overflow-hidden">
                  <div
                    className="bg-yellow-500 h-full rounded-full"
                    style={{ width: `${pct}%` }}
                  ></div>
                </div>
                <span className="w-6 text-gray-500">{count}</span>
              </div>
            );
          })}
        </div>
      </div>

      <div className="space-y-4">
        {reviews.map((review, idx) => (
          <div key={idx} className="bg-white border border-gray-200 rounded-lg p-4">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-gray-300 rounded-full flex items-center justify-center text-white text-xs font-bold">
                  {review.user.charAt(0)}
                </div>
                <span className="text-sm font-bold text-gray-800">{review.user}</span>
              </div>
              <span className="text-xs text-gray-500">{review.date}</span>
            </div>
            <div className="flex text-yellow-500 text-xs mb-2">
              {[...Array(5)].map((_, i) => (
                <i key={i} className={i < review.rating ? 'ri-star-fill' : 'ri-star-line'}></i>
              ))}
            </div>
            <p className="text-sm text-gray-700 leading-relaxed">{review.comment}</p>
          </div>
        ))}
      </div>
    </div>
  );
}
