import { useParams, Link } from 'react-router-dom';
import { productDetails } from '../../mocks/productDetails';
import ProductImages from './components/ProductImages';
import ProductInfo from './components/ProductInfo';
import ProductSpecs from './components/ProductSpecs';
import ProductReviews from './components/ProductReviews';
import RelatedProducts from './components/RelatedProducts';
import GlobalHeader from '../../components/feature/GlobalHeader';
import GlobalFooter from '../../components/feature/GlobalFooter';
import Breadcrumb from '../../components/feature/Breadcrumb';

export default function ProductDetail() {
  const { id } = useParams<{ id: string }>();
  const product = productDetails.find((p) => p.id === Number(id));

  if (!product) {
    return (
      <div className="min-h-screen bg-white flex flex-col items-center justify-center">
        <i className="ri-error-warning-line text-6xl text-gray-300 mb-4"></i>
        <p className="text-xl text-gray-600 mb-4">商品が見つかりませんでした</p>
        <Link to="/" className="bg-red-600 text-white px-6 py-3 rounded-lg font-bold hover:bg-red-700 cursor-pointer whitespace-nowrap">
          トップページへ戻る
        </Link>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-white">
      {/* 共通ヘッダー */}
      <GlobalHeader />

      {/* パンくずリスト */}
      <Breadcrumb items={[
        { label: 'ショッピング', to: '/shop' },
        { label: product.brand },
        { label: product.name }
      ]} />

      {/* 商品メインエリア */}
      <main className="max-w-[1400px] mx-auto px-6 pb-8">
        <div className="grid grid-cols-2 gap-10 mb-12">
          <ProductImages images={product.images} name={product.name} />
          <ProductInfo
            brand={product.brand}
            name={product.name}
            price={product.price}
            originalPrice={product.originalPrice}
            discount={product.discount}
            tags={product.tags}
            sku={product.sku}
            shipping={product.shipping}
            points={product.points}
            stock={product.stock}
          />
        </div>

        <div className="grid grid-cols-3 gap-8">
          <div className="col-span-2 space-y-10">
            <ProductSpecs description={product.description} specs={product.specs} />
            <ProductReviews reviews={product.reviews} />
          </div>
          <div>
            <RelatedProducts relatedIds={product.relatedIds} />

            {/* サイドバナー */}
            <div className="mt-6 space-y-3">
              <div className="bg-gradient-to-r from-orange-500 to-red-500 p-4 rounded-lg cursor-pointer hover:opacity-90">
                <p className="text-white font-bold text-sm leading-tight">
                  今なら取付商品全品<br />+5%ポイント還元
                </p>
              </div>
              <div className="bg-gradient-to-r from-green-600 to-green-500 p-4 rounded-lg cursor-pointer hover:opacity-90">
                <p className="text-white font-bold text-sm leading-tight">
                  車検取得で<br />最大15,000円分ポイント
                </p>
              </div>
            </div>
          </div>
        </div>
      </main>

      {/* フッター */}
      <GlobalFooter />
    </div>
  );
}
